CREATE TYPE "QueueType" AS ENUM ('CODING','DOCUMENTATION','AUTHORIZATION','DENIAL','APPEAL','PAYMENT','AR_FOLLOWUP','OTHER');
CREATE TYPE "WorkPriority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "WorkItemStatus" AS ENUM ('OPEN','ASSIGNED','IN_PROGRESS','BLOCKED','COMPLETED','CANCELED');
CREATE TYPE "DenialStatus" AS ENUM ('OPEN','UNDER_REVIEW','APPEAL_CANDIDATE','APPEALED','OVERTURNED','UPHELD','WRITTEN_OFF','CLOSED');
CREATE TYPE "AppealStatus" AS ENUM ('DRAFT','READY_FOR_REVIEW','APPROVED_FOR_SUBMISSION','SUBMITTED','PAYER_REVIEW','WON','LOST','PARTIAL','WITHDRAWN');
CREATE TYPE "ReimbursementEventType" AS ENUM ('PAYMENT','ADJUSTMENT','REFUND','RECOUPMENT','WRITE_OFF','TRANSFER');
CREATE TYPE "AssignmentStrategy" AS ENUM ('MANUAL','ROUND_ROBIN','LEAST_LOADED','RULE_BASED');
CREATE TABLE "WorkQueue" ("id" TEXT PRIMARY KEY,"practiceId" TEXT NOT NULL,"name" TEXT NOT NULL,"queueType" "QueueType" NOT NULL,"description" TEXT,"assignmentStrategy" "AssignmentStrategy" NOT NULL DEFAULT 'MANUAL',"configuration" JSONB NOT NULL DEFAULT '{}',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "WorkItem" ("id" TEXT PRIMARY KEY,"practiceId" TEXT NOT NULL,"queueId" TEXT NOT NULL,"claimId" TEXT,"encounterId" TEXT,"assignedUserId" TEXT,"priority" "WorkPriority" NOT NULL DEFAULT 'NORMAL',"status" "WorkItemStatus" NOT NULL DEFAULT 'OPEN',"title" TEXT NOT NULL,"description" TEXT NOT NULL,"dueAt" TIMESTAMP(3),"sourceType" TEXT NOT NULL,"sourceId" TEXT,"resolutionCode" TEXT,"resolutionNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"completedAt" TIMESTAMP(3));
CREATE TABLE "DenialCase" ("id" TEXT PRIMARY KEY,"practiceId" TEXT NOT NULL,"claimId" TEXT NOT NULL,"denialCode" TEXT,"denialReason" TEXT NOT NULL,"denialCategory" TEXT NOT NULL,"denialDate" TIMESTAMP(3) NOT NULL,"appealDeadline" TIMESTAMP(3),"amountAtRisk" DECIMAL(12,2) NOT NULL,"status" "DenialStatus" NOT NULL DEFAULT 'OPEN',"sourceReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Appeal" ("id" TEXT PRIMARY KEY,"denialCaseId" TEXT NOT NULL,"status" "AppealStatus" NOT NULL DEFAULT 'DRAFT',"appealLevel" TEXT NOT NULL,"draftTextEncrypted" TEXT,"evidenceManifest" JSONB NOT NULL DEFAULT '[]',"reviewerId" TEXT,"approvedAt" TIMESTAMP(3),"submittedAt" TIMESTAMP(3),"decisionAt" TIMESTAMP(3),"outcome" TEXT,"recoveredAmount" DECIMAL(12,2),"externalReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ReimbursementEvent" ("id" TEXT PRIMARY KEY,"practiceId" TEXT NOT NULL,"claimId" TEXT NOT NULL,"eventType" "ReimbursementEventType" NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'USD',"paymentDate" TIMESTAMP(3) NOT NULL,"source" TEXT NOT NULL,"externalReferenceHash" TEXT,"remittanceMetadata" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "WorkQueue_practiceId_name_key" ON "WorkQueue"("practiceId","name");
CREATE INDEX "WorkQueue_practiceId_queueType_active_idx" ON "WorkQueue"("practiceId","queueType","active");
CREATE INDEX "WorkItem_practiceId_status_priority_dueAt_idx" ON "WorkItem"("practiceId","status","priority","dueAt");
CREATE INDEX "WorkItem_queueId_status_createdAt_idx" ON "WorkItem"("queueId","status","createdAt");
CREATE INDEX "WorkItem_assignedUserId_status_dueAt_idx" ON "WorkItem"("assignedUserId","status","dueAt");
CREATE INDEX "DenialCase_practiceId_status_denialDate_idx" ON "DenialCase"("practiceId","status","denialDate");
CREATE INDEX "DenialCase_claimId_status_idx" ON "DenialCase"("claimId","status");
CREATE INDEX "DenialCase_appealDeadline_status_idx" ON "DenialCase"("appealDeadline","status");
CREATE INDEX "Appeal_denialCaseId_status_idx" ON "Appeal"("denialCaseId","status");
CREATE INDEX "Appeal_status_submittedAt_idx" ON "Appeal"("status","submittedAt");
CREATE INDEX "ReimbursementEvent_practiceId_paymentDate_eventType_idx" ON "ReimbursementEvent"("practiceId","paymentDate","eventType");
CREATE INDEX "ReimbursementEvent_claimId_paymentDate_idx" ON "ReimbursementEvent"("claimId","paymentDate");
