ALTER TABLE "WorkItem" ADD CONSTRAINT "WorkItem_encounterId_fkey" FOREIGN KEY("encounterId") REFERENCES "Encounter"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkItem" ADD CONSTRAINT "WorkItem_assignedUserId_fkey" FOREIGN KEY("assignedUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "DenialCase" ADD CONSTRAINT "DenialCase_practiceId_fkey" FOREIGN KEY("practiceId") REFERENCES "Practice"("id") ON DELETE CASCADE ON UPDATE CASCADE;
